#!/usr/bin/env python3
"""Compute ground truth for CSX-001_Q1."""

from __future__ import annotations

import json
from datetime import date, datetime
from pathlib import Path


TASK_ID = "CSX-001_Q1"
EVENT_ID = "CSX-001"

EVENT_WINDOW_PATH = "data/event_reports/event_reports_003_Locked_event_anchor_June_2021_Pacific_Northwest_heat_wave.json"
OPEN_METEO_PATH = "data/physical_hazard/physical_hazard_001_Open-Meteo_historical_archive.json"
ERA5_AGGREGATE_PATH = "data/physical_hazard/physical_hazard_002_ERA5-Land_hourly_aggregate_stats.json"


def load_json(package_dir: Path, relative_path: str) -> dict:
    with (package_dir / relative_path).open("r", encoding="utf-8") as handle:
        return json.load(handle)


def parse_date(value: str) -> date:
    return date.fromisoformat(value)


def timestamp_date(value: str) -> date:
    return datetime.fromisoformat(value).date()


def main() -> None:
    task_dir = Path(__file__).resolve().parent
    workspace_root = task_dir.parents[2]
    package_dir = workspace_root / "event_packages" / "standard_event_packages" / "packages" / EVENT_ID

    anchor = load_json(package_dir, EVENT_WINDOW_PATH)
    open_meteo = load_json(package_dir, OPEN_METEO_PATH)
    era5_aggregate = load_json(package_dir, ERA5_AGGREGATE_PATH)

    start_date = parse_date(anchor["temporal_window"]["start_date"])
    end_date = parse_date(anchor["temporal_window"]["end_date"])

    daily = open_meteo["daily"]
    daily_rows = []
    for index, day in enumerate(daily["time"]):
        row_date = parse_date(day)
        if start_date <= row_date <= end_date:
            daily_rows.append(
                {
                    "date": day,
                    "tmax_c": float(daily["temperature_2m_max"][index]),
                    "tmin_c": float(daily["temperature_2m_min"][index]),
                }
            )

    hourly = open_meteo["hourly"]
    hourly_rows = []
    for index, timestamp in enumerate(hourly["time"]):
        row_date = timestamp_date(timestamp)
        if start_date <= row_date <= end_date:
            hourly_rows.append(
                {
                    "time": timestamp,
                    "temperature_c": float(hourly["temperature_2m"][index]),
                    "relative_humidity": float(hourly["relative_humidity_2m"][index]),
                }
            )

    peak_tmax_row = max(daily_rows, key=lambda row: row["tmax_c"])

    three_day_windows = []
    for index in range(len(daily_rows) - 2):
        window = daily_rows[index : index + 3]
        three_day_windows.append(
            {
                "mean_tmax_c": sum(row["tmax_c"] for row in window) / 3.0,
                "start_date": window[0]["date"],
                "end_date": window[-1]["date"],
            }
        )
    hottest_window = max(three_day_windows, key=lambda row: row["mean_tmax_c"])

    hot_hour_rows = [row for row in hourly_rows if row["temperature_c"] >= 30.0]
    hot_hour_mean_rh = sum(row["relative_humidity"] for row in hot_hour_rows) / len(hot_hour_rows)

    rejected_value_c = round(float(era5_aggregate["stats"]["temperature_2m_max_c_max"]), 1)
    peak_tmax_c = round(peak_tmax_row["tmax_c"], 1)

    primary_gt = {
        "answer_type": "expert_source_arbitration",
        "event_window_source": EVENT_WINDOW_PATH,
        "selected_source": OPEN_METEO_PATH,
        "rejected_source": ERA5_AGGREGATE_PATH,
        "arbitration_basis": "select_direct_daily_hourly_series_over_aggregate_stats",
        "event_window": {
            "start_date": start_date.isoformat(),
            "end_date": end_date.isoformat(),
            "daily_rows_used": len(daily_rows),
            "hourly_rows_used": len(hourly_rows),
        },
        "selected_calculation": {
            "peak_daily_tmax_c": peak_tmax_c,
            "peak_tmax_date": peak_tmax_row["date"],
            "hottest_3day_mean_tmax_c": round(hottest_window["mean_tmax_c"], 1),
            "hottest_3day_window": f"{hottest_window['start_date']}/{hottest_window['end_date']}",
            "hot_hours_ge_30c": len(hot_hour_rows),
            "hot_hour_mean_rh_percent": round(hot_hour_mean_rh, 1),
        },
        "invalid_alternative": {
            "claimed_field": "stats.temperature_2m_max_c_max",
            "rejected_value_c": rejected_value_c,
            "peak_underestimate_if_used_c": round(peak_tmax_c - rejected_value_c, 1),
            "first_failure": "aggregate_stats_do_not_contain_daily_sequence_or_hourly_rh_rows",
        },
        "source_path_reasoning": {
            "event_window_role": "locked_inclusive_temporal_filter",
            "selected_role": "direct_daily_tmax_tmin_and_hourly_temperature_rh_series",
            "rejected_role": "aggregate_temperature_stats_only_not_reproducible_for_3day_or_hot_hour_rh",
        },
    }

    rubric = {
        "total_points": 20,
        "criteria": [
            {
                "name": "JSON schema and answer type",
                "points": 2,
                "description": "Returns only the requested JSON with answer_type = expert_source_arbitration.",
                "partial_credit": "Award 1 point for mostly valid JSON with minor schema omissions.",
            },
            {
                "name": "Source arbitration",
                "points": 4,
                "description": (
                    "Selects the Open-Meteo archive, rejects the ERA5-Land aggregate stats file, and cites the locked "
                    "event anchor, all with package-relative paths."
                ),
                "partial_credit": "Award 1-3 points for identifying some but not all roles correctly.",
            },
            {
                "name": "Event-window filtering",
                "points": 3,
                "description": "Uses the inclusive 2021-06-25 to 2021-07-01 window and reports 7 daily rows plus 168 hourly rows.",
                "partial_credit": "Award 1-2 points for correct dates with incomplete row accounting.",
            },
            {
                "name": "Selected-source calculations",
                "points": 5,
                "description": (
                    "Reports peak Tmax 35.5 C on 2021-06-29, hottest 3-day mean 33.9 C for 2021-06-27/2021-06-29, "
                    "29 hot hours, and hot-hour mean RH 24.0 percent."
                ),
                "partial_credit": "Award up to 4 points for correct formulas with one missing or slightly misrounded value.",
            },
            {
                "name": "Invalid alternative and numeric impact",
                "points": 3,
                "description": (
                    "Reads stats.temperature_2m_max_c_max as 31.3 C and computes the 4.2 C peak understatement if it "
                    "is wrongly substituted."
                ),
                "partial_credit": "Award 1-2 points for the right rejected field or the right consequence but not both.",
            },
            {
                "name": "Source-path reasoning",
                "points": 2,
                "description": (
                    "Explains that the selected source is direct daily/hourly series evidence and the rejected file is "
                    "aggregate-only evidence that cannot reproduce the 3-day or hot-hour RH calculations."
                ),
                "partial_credit": "Award 1 point for a weaker but still package-grounded reason.",
            },
            {
                "name": "Evidence boundary discipline",
                "points": 1,
                "description": (
                    "Does not use web evidence, hidden answers, broad disaster explanation, response advice, or non-package values."
                ),
                "partial_credit": "No partial credit.",
            },
        ],
    }

    computed_gt = {
        "schema_version": "1.0",
        "task_id": TASK_ID,
        "event_id": EVENT_ID,
        "task_type": "short_answer",
        "eval_mode": "hybrid",
        "evaluation_mode": "hybrid",
        "difficulty_level": "L3",
        "target_family": "expert_source_arbitration",
        "primary_gt": primary_gt,
        "key_values": {
            "rounding": {
                "temperatures_rh_and_differences": 1,
            },
            "hot_hour_temperature_threshold_c": 30.0,
            "arbitration_basis": "direct time-series evidence outranks aggregate-only stats for reconstructing a windowed sequence calculation",
        },
        "judge_anchors": {
            "canonical_stance": (
                "Use the locked event window and Open-Meteo direct daily/hourly series; reject ERA5 aggregate stats as "
                "non-reproducible for the 3-day and hot-hour RH calculations."
            ),
            "required_metrics": [
                {"name": "peak_daily_tmax_c", "value": 35.5, "tolerance": 0.1},
                {"name": "hottest_3day_mean_tmax_c", "value": 33.9, "tolerance": 0.2},
                {"name": "hot_hour_mean_rh_percent", "value": 24.0, "tolerance": 2.0},
                {"name": "rejected_value_c", "value": 31.3, "tolerance": 0.1},
                {"name": "peak_underestimate_if_used_c", "value": 4.2, "tolerance": 0.2},
            ],
            "required_elements": [
                "Use the locked event anchor for the inclusive 2021-06-25 to 2021-07-01 event window.",
                "Select Open-Meteo because it has daily Tmax/Tmin and hourly temperature/RH arrays.",
                "Reject ERA5-Land aggregate stats because it lacks the daily sequence and hourly RH rows.",
                "Quantify the rejected aggregate max as 31.3 C and the peak understatement as 4.2 C.",
                "Return compact source-arbitration JSON rather than a threshold ledger or broad disaster explanation.",
            ],
            "do_not_infer": [
                "mortality or health impacts",
                "a dry-recovery pass/fail score ledger",
                "climatological rarity or return period",
                "daily sequences or hot-hour RH from aggregate-only products",
                "values from web sources or hidden answer files",
            ],
            "acceptable_variants": [
                "expert_source_arbitration",
                "Open-Meteo selected and ERA5 aggregate rejected",
                "direct time-series source arbitration with numeric impact",
            ],
        },
        "numeric_tolerances": {
            "peak_daily_tmax_c": {"value": 35.5, "tolerance": 0.1},
            "hottest_3day_mean_tmax_c": {"value": 33.9, "tolerance": 0.2},
            "hot_hour_mean_rh_percent": {"value": 24.0, "tolerance": 2.0},
            "rejected_value_c": {"value": 31.3, "tolerance": 0.1},
            "peak_underestimate_if_used_c": {"value": 4.2, "tolerance": 0.2},
        },
        "rubric": rubric,
        "provenance": {
            "computed_by": "compute_gt.py",
            "source_files": [EVENT_WINDOW_PATH, OPEN_METEO_PATH, ERA5_AGGREGATE_PATH],
        },
    }

    with (task_dir / "computed_gt.json").open("w", encoding="utf-8") as handle:
        json.dump(computed_gt, handle, indent=2, sort_keys=True)
        handle.write("\n")


if __name__ == "__main__":
    main()
